add_action( 'woocommerce_after_calculate_totals', 'perfectpixel_remove_product_when_condition_fails' );

function perfectpixel_remove_product_condition( $cart, $product_id ) {
	// Remove when the subtotal of the OTHER products is below the threshold.
	$subtotal = 0;
	foreach ( $cart->get_cart() as $item ) {
		if ( (int) $item['product_id'] !== $product_id ) {
			$subtotal += $item['line_subtotal'];
		}
	}
	return $subtotal < (float) '{{remove_below_amount}}';
}

function perfectpixel_remove_product_when_condition_fails( $cart ) {
	static $running = false;
	$product_id = (int) '{{remove_product_id}}';
	if ( $running || ! $product_id ) {
		return;
	}
	foreach ( $cart->get_cart() as $key => $item ) {
		if ( (int) $item['product_id'] === $product_id && perfectpixel_remove_product_condition( $cart, $product_id ) ) {
			$running = true;
			$cart->remove_cart_item( $key );
			$running = false;
			break;
		}
	}
}
